class CloudGnbSnapshotCollectorConfigurator:
    def __get_webservice_vdu(self, vdu_id):
        vdu_http_connection_details = self.tl_config_information_provider.get_vdu_oam_http_connection_details(vdu_id=vdu_id)
        vdu_http_connection_details['vdu_version'] = 'cuoam_23r2'
        return vdu_http_connection_details

    def __get_webservice_vcu(self):
        cu_http_connection_details = self.tl_config_information_provider.get_cu_oam_http_connection_details()
        cu_http_connection_details['cu_version'] = 'cuoam_23r2'
        return cu_http_connection_details

    def add_snapshot(self, ne_log_name, ne_log_configuration):
        list_of_names = []

        for vdu_id in self.tl_config_information_provider.get_du_ids(node_id=self.ne_id):
            webservice_vdu = self.__get_webservice_vdu(vdu_id)
            vdu_full_name = f"{ne_log_name}_du_{vdu_id}"
            snapshot_vdu_collector_configuration = {
                'name': vdu_full_name,
                'type': "snapshot_asynchronous_coam_vdu",
                'webservice': webservice_vdu}
            self._collector_configuration_data.append(snapshot_vdu_collector_configuration)
            list_of_names.append(vdu_full_name)

        vcu_full_name = f"{ne_log_name}_cu_0"
        webservice_vcu = self.__get_webservice_vcu()
        snapshot_vcu_collector_configuration = {
            'name': vcu_full_name,
            'type': "snapshot_asynchronous_coam_cu",
            'webservice': webservice_vcu}
        self._collector_configuration_data.append(snapshot_vcu_collector_configuration)
        list_of_names.append(vcu_full_name)

        snapshot_group_collector = {
            'type': 'group',
            'name': f'{ne_log_name}',
            'members': list_of_names}

        self._collector_configuration_data.append(snapshot_group_collector)

        self._collector_configuration_data.add_mapping_entry(
            log_type='snapshot',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=snapshot_group_collector)
